import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 2

def design(feats):
    # Filter out near-duplicates based on correlation
    corr_pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # Group correlated features and keep one from each group
    groups = []
    used = set()
    for fid1, fid2 in corr_pairs:
        if fid1 not in used and fid2 not in used:
            groups.append([fid1, fid2])
            used.add(fid1)
            used.add(fid2)
        elif fid1 in used and fid2 not in used:
            for group in groups:
                if fid1 in group:
                    group.append(fid2)
                    used.add(fid2)
                    break
        elif fid2 in used and fid1 not in used:
            for group in groups:
                if fid2 in group:
                    group.append(fid1)
                    used.add(fid1)
                    break

    # Add remaining features as singleton groups
    for fid in feats.ids:
        if fid not in used:
            groups.append([fid])

    # Select representative feature from each group (highest mean_y1-mean_y0)
    selected_features = []
    for group in groups:
        best_fid = max(group, key=lambda fid: abs(np.mean(feats.x[feats.y==1, feats.column(fid)] - 
                                                          feats.x[feats.y==0, feats.column(fid)])))
        selected_features.append(best_fid)

    # Compute effect sizes for selected features
    effect_sizes = []
    for fid in selected_features:
        col_idx = feats.column(fid)
        effect_size = np.mean(feats.x[feats.y==1, col_idx]) - np.mean(feats.x[feats.y==0, col_idx])
        effect_sizes.append((fid, abs(effect_size)))

    # Sort by effect size and take top 2
    effect_sizes.sort(key=lambda x: x[1], reverse=True)
    drivers = [fid for fid, _ in effect_sizes[:MAX_DRIVERS]]

    # Build columns, products, and loadings
    columns = selected_features
    products = []
    loadings = {}

    # Simple weighted sum using effect sizes as weights
    for fid, effect_size in effect_sizes:
        loadings[fid] = effect_size

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)
